import numpy as np
from scipy.optimize import minimize


def _radii_from_centers(centers):
    """True optimal radius assignment for fixed centers:
    r_i = min(wall distance, half gap to every neighbor)."""
    centers = np.asarray(centers, dtype=float)
    n = centers.shape[0]
    walls = np.minimum(np.minimum(centers[:, 0], centers[:, 1]),
                       np.minimum(1.0 - centers[:, 0], 1.0 - centers[:, 1]))
    radii = walls.copy()
    for i in range(n):
        for j in range(i + 1, n):
            d = float(np.hypot(centers[i, 0] - centers[j, 0],
                               centers[i, 1] - centers[j, 1]))
            h = 0.5 * d
            if h < radii[i]:
                radii[i] = h
            if h < radii[j]:
                radii[j] = h
    return np.maximum(radii, 0.0)


def construct_packing():
    n = 26
    best_centers = None
    best_sum = -1

    inits = []
    # Hex lattice with various spacings
    for s in [0.14, 0.15, 0.16, 0.17]:
        pts = hex_lattice(s)
        if len(pts) >= 26:
            dists = np.sqrt((pts[:, 0] - 0.5)**2 + (pts[:, 1] - 0.5)**2)
            idx = np.argsort(dists)
            inits.append(pts[idx[:26]].copy())
    # Grid 5x5 + 1
    grid_pts = []
    for i in range(5):
        for j in range(5):
            grid_pts.append([0.1 + i*0.2, 0.1 + j*0.2])
    grid_pts.append([0.5, 0.5])
    inits.append(np.array(grid_pts[:26]))
    # Structured rows
    for config in [[5,5,5,5,5,1], [4,5,5,5,5,2], [3,5,5,5,5,3]]:
        inits.append(row_config(config))

    for init in inits:
        result = minimize(
            lambda x: -np.sum(_radii_from_centers(x.reshape(26, 2))),
            init.flatten(),
            method='L-BFGS-B',
            bounds=[(0.01, 0.99)] * 52,
            options={'maxiter': 200, 'ftol': 1e-8}
        )
        opt_centers = result.x.reshape(26, 2)
        radii = _radii_from_centers(opt_centers)
        s_sum = np.sum(radii)
        if s_sum > best_sum:
            best_sum = s_sum
            best_centers = opt_centers.copy()

    radii = _radii_from_centers(best_centers)
    return best_centers, radii, float(np.sum(radii))


def hex_lattice(s):
    dy = s * np.sqrt(3) / 2
    pts = []
    row = 0
    y = 0.02
    while y <= 0.98:
        x_offset = (s / 2) if (row % 2 == 1) else 0
        x = 0.02 + x_offset
        while x <= 0.98:
            pts.append([x, y])
            x += s
        y += dy
        row += 1
    return np.array(pts)


def row_config(config):
    n = sum(config)
    n_rows = len(config)
    dy = 1.0 / (n_rows + 1)
    centers = np.zeros((n, 2))
    idx = 0
    for r in range(n_rows):
        n_in_row = config[r]
        y = dy * (r + 1)
        if n_in_row > 1:
            xs = np.linspace(0.1, 0.9, n_in_row)
        else:
            xs = np.array([0.5])
        for x in xs:
            centers[idx] = [x, y]
            idx += 1
    return centers"}

