"""Constructor-based circle packing for n=26 circles"""
import numpy as np
from scipy.optimize import linprog, minimize


def solve_max_radii_lp(centers):
    """Maximize sum r_i s.t. r_i + r_j <= d_ij and r_i <= wall_i."""
    n = centers.shape[0]
    c = -np.ones(n)
    A_rows = []
    b_vals = []
    for i in range(n):
        for j in range(i + 1, n):
            d = np.sqrt(np.sum((centers[i] - centers[j]) ** 2))
            row = np.zeros(n)
            row[i] = 1
            row[j] = 1
            A_rows.append(row)
            b_vals.append(d)
    for i in range(n):
        x, y = centers[i]
        b_dist = min(x, y, 1 - x, 1 - y)
        row = np.zeros(n)
        row[i] = 1
        A_rows.append(row)
        b_vals.append(b_dist)
    A = np.array(A_rows)
    b = np.array(b_vals)
    bounds = [(0, None)] * n
    result = linprog(c, A_ub=A, b_ub=b, bounds=bounds, method='highs')
    if result.success:
        return np.maximum(result.x, 0)
    return compute_max_radii_fallback(centers)


def compute_max_radii_fallback(centers):
    n = centers.shape[0]
    radii = np.ones(n)
    for i in range(n):
        x, y = centers[i]
        radii[i] = min(x, y, 1 - x, 1 - y)
    for _ in range(200):
        for i in range(n):
            for j in range(i + 1, n):
                dist = np.sqrt(np.sum((centers[i] - centers[j]) ** 2))
                if radii[i] + radii[j] > dist:
                    scale = dist / (radii[i] + radii[j])
                    radii[i] *= scale
                    radii[j] *= scale
    return radii


def lp_sum(centers):
    return np.sum(solve_max_radii_lp(centers))


def construct_packing():
    n = 26
    best_centers = None
    best_sum = -1

    inits = []
    for s in [0.14, 0.15, 0.16, 0.17]:
        pts = hex_lattice(s)
        if len(pts) >= 26:
            dists = np.sqrt((pts[:, 0] - 0.5)**2 + (pts[:, 1] - 0.5)**2)
            idx = np.argsort(dists)
            inits.append(pts[idx[:26]].copy())
    grid_pts = []
    for i in range(5):
        for j in range(5):
            grid_pts.append([0.1 + i*0.2, 0.1 + j*0.2])
    grid_pts.append([0.5, 0.5])
    inits.append(np.array(grid_pts[:26]))
    for config in [[5,5,5,5,5,1], [4,5,5,5,5,2], [3,5,5,5,5,3]]:
        inits.append(row_config(config))

    # Optimize each init with L-BFGS-B (same as seed) but fewer iters,
    # then refine the best with Nelder-Mead on the LP-sum objective.
    for init in inits:
        result = minimize(
            lambda x: -lp_sum(x.reshape(26, 2)),
            init.flatten(),
            method='L-BFGS-B',
            bounds=[(0.01, 0.99)] * 52,
            options={'maxiter': 120, 'ftol': 1e-8}
        )
        opt_centers = result.x.reshape(26, 2)
        radii = solve_max_radii_lp(opt_centers)
        s_sum = np.sum(radii)
        if s_sum > best_sum:
            best_sum = s_sum
            best_centers = opt_centers.copy()

    # Nelder-Mead refinement of the best arrangement
    try:
        nm = minimize(
            lambda x: -lp_sum(x.reshape(26, 2)),
            best_centers.flatten(),
            method='Nelder-Mead',
            options={'maxiter': 3000, 'xatol': 1e-5, 'fatol': 1e-7,
                     'adaptive': True}
        )
        nm_centers = np.clip(nm.x.reshape(26, 2), 0.01, 0.99)
        nm_radii = solve_max_radii_lp(nm_centers)
        nm_sum = np.sum(nm_radii)
        if nm_sum > best_sum:
            best_sum = nm_sum
            best_centers = nm_centers.copy()
    except Exception:
        pass

    radii = solve_max_radii_lp(best_centers)
    return best_centers, radii, float(np.sum(radii))


