            d = np.sqrt(np.sum((centers[i] - centers[j]) ** 2))
            row = np.zeros(n)
            row[i] = 1
            row[j] = 1
            A_rows.append(row)
            b_vals.append(d)
    for i in range(n):
        x, y = centers[i]
        b_dist = min(x, y, 1 - x, 1 - y)
        row = np.zeros(n)
        row[i] = 1
        A_rows.append(row)
        b_vals.append(b_dist)
    A = np.array(A_rows)
    b = np.array(b_vals)
    bounds = [(0, None)] * n
    result = linprog(c, A_ub=A, b_ub=b, bounds=bounds, method='highs')
    if result.success:
        return np.maximum(result.x, 0)
    return compute_max_radii_fallback(centers)


def compute_max_radii_fallback(centers):
    n = centers.shape[0]
    radii = np.ones(n)
    for i in range(n):
        x, y = centers[i]
        radii[i] = min(x, y, 1 - x, 1 - y)
    for _ in range(200):
        for i in range(n):
            for j in range(i + 1, n):
                dist = np.sqrt(np.sum((centers[i] - centers[j]) ** 2))
                if radii[i] + radii[j] > dist:
                    scale = dist / (radii[i] + radii[j])
                    radii[i] *= scale
                    radii[j] *= scale
    return radii


def lp_sum(centers):
    return np.sum(solve_max_radii_lp(centers))


def jittered_grid(seed):
    rng = np.random.RandomState(seed)
    pts = []
    for i in range(5):
        for j in range(5):
            pts.append([0.1 + 0.2*i, 0.1 + 0.2*j])
    pts.append([0.5, 0.5])
    pts = np.array(pts)
    pts += rng.uniform(-0.04, 0.04, size=pts.shape)
    return np.clip(pts, 0.02, 0.98)


def construct_packing():
    n = 26
    best_centers = None
    best_sum = -1

    # Only the productive jittered seeds, with a modest maxiter to stay fast
    for seed in [7, 13, 29, 42, 55, 71, 88]:
        init = jittered_grid(seed)
        result = minimize(
            lambda x: -lp_sum(x.reshape(26, 2)),
            init.flatten(),
            method='L-BFGS-B',
            bounds=[(0.01, 0.99)] * 52,
            options={'maxiter': 100, 'ftol': 1e-8}
        )
        opt_centers = result.x.reshape(26, 2)
        radii = solve_max_radii_lp(opt_centers)
        s_sum = np.sum(radii)
        if s_sum > best_sum:
            best_sum = s_sum
            best_centers = opt_centers.copy()

    radii = solve_max_radii_lp(best_centers)
    return best_centers, radii, float(np.sum(radii))"}
